    !> @brief Evaluate one standard-sized chunk of the immutable PIP operation graph.
    pure subroutine evaluate_operation_chunk( first_operation, operation_data, node_values )
        integer, intent(in)     :: first_operation, operation_data(:,:)
        real(wp), intent(inout) :: node_values(:)
        integer                 :: local_operation, node
        do local_operation=1, size(operation_data, 2)
            node = initial_node_count+first_operation+local_operation-1
            select case(operation_data(1,local_operation))
            case(add_operation)
                node_values(node) = node_values(operation_data(2,local_operation))+ node_values(operation_data(3, &
                    & local_operation))
            case(subtract_operation)
                node_values(node) = node_values(operation_data(2,local_operation))- node_values(operation_data(3, &
                    & local_operation))
            case(multiply_operation)
                node_values(node) = node_values(operation_data(2,local_operation))* node_values(operation_data(3, &
                    & local_operation))
            end select
        enddo
    end subroutine evaluate_operation_chunk

    !> @brief Reverse-accumulate one standard-sized chunk of the PIP operation graph.
    pure subroutine reverse_operation_chunk( first_operation, operation_data, node_values, adjoints )
        integer, intent(in)     :: first_operation, operation_data(:,:)
        real(wp), intent(in)    :: node_values(:)
        real(wp), intent(inout) :: adjoints(:)
        integer                 :: local_operation, node
        do local_operation=size(operation_data, 2), 1, -1
            node = initial_node_count+first_operation+local_operation-1
            select case(operation_data(1,local_operation))
            case(add_operation)
                adjoints(operation_data(2,local_operation)) = adjoints(operation_data(2,local_operation))+ &
                    & adjoints(node)
                adjoints(operation_data(3,local_operation)) = adjoints(operation_data(3,local_operation))+ &
                    & adjoints(node)
            case(subtract_operation)
                adjoints(operation_data(2,local_operation)) = adjoints(operation_data(2,local_operation))+ &
                    & adjoints(node)
                adjoints(operation_data(3,local_operation)) = adjoints(operation_data(3,local_operation))- &
                    & adjoints(node)
            case(multiply_operation)
                adjoints(operation_data(2,local_operation)) = adjoints(operation_data(2,local_operation))+ &
                    & adjoints(node)*node_values(operation_data(3,local_operation))
                adjoints(operation_data(3,local_operation)) = adjoints(operation_data(3,local_operation))+ &
                    & adjoints(node)*node_values(operation_data(2,local_operation))
            end select
        enddo
    end subroutine reverse_operation_chunk
end module chempotpy_h5o2p_pip_basis
